// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    // Fuzz parameters: depositor private key (so we can vm.addr it) and deposit amount
    function testFuzz_property(uint256 depositorKey, uint256 depositAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        depositorKey = bound(depositorKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // Bound depositAmount to a reasonable non-zero value and avoid underflowing vm.deal
        depositAmount = bound(depositAmount, 1, 1 ether);

        address depositor = vm.addr(depositorKey);

        // Deploy a callee that ALWAYS reverts on receive; this models a failing external transfer
        Reverter bad = new Reverter();

        // Fund depositor so they can call deposit
        vm.deal(depositor, depositAmount);

        // Make deposit from depositor
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        // Now replace depositor's address with the Reverter by making the Reverter be the msg.sender
        // We need to have the mapping keyed by msg.sender be the reverter address. So instead, perform
        // deposit from the Reverter contract by funding it and calling deposit through it.
        // Fund the Reverter
        vm.deal(address(bad), depositAmount);

        // Have the Reverter deposit into c
        bad.doDeposit{value: depositAmount}(c);

        // Sanity: c should have recorded balance via its public balance variable (no getter; use address(c).balance)
        // Now attempt withdrawAll from the Reverter which will revert when c.call is attempted.
        // Call withdrawAll and observe whether it reverts. The reference contract MUST revert when the low-level
        // call to the recipient reverts; the mutant will NOT revert and will leave credit zero but balance decremented.

        bool ok;
        // We must call withdrawAll as the Reverter (so msg.sender is the Reverter) and capture whether it reverts
        try bad.doWithdrawAll(c) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE ASSERTION (single assertTrue): For the reference, withdrawAll reverts when the recipient's
        // fallback/receive reverts. Therefore ok must be false for that scenario. The mutant (missing require)
        // will make ok true for at least some inputs (the fuzz will find one) and thus fail this assert.
        assertTrue(!ok);
    }
}

// Adversarial helper that reverts on receive and can call C on its behalf
contract Reverter {
    // Allow reverter to call deposit on c
    function doDeposit(ReentrancyDAO c) external payable {
        c.deposit{value: msg.value}();
    }

    // Call withdrawAll on c; when c attempts to send ETH back, this contract will revert in receive()
    function doWithdrawAll(ReentrancyDAO c) external {
        c.withdrawAll();
    }

    // Revert on any incoming ETH
    receive() external payable {
        revert("revert receive");
    }
}
